import{_ as t,c as e,o as i,V as a}from"./chunks/framework.GYYi-SO7.js";const y=JSON.parse('{"title":"nb04 · JSON chunking","description":"","frontmatter":{},"headers":[],"relativePath":"research/json-chunking.md","filePath":"research/json-chunking.md"}'),r={name:"research/json-chunking.md"},s=a('<h1 id="nb04-·-json-chunking" tabindex="-1">nb04 · JSON chunking <a class="header-anchor" href="#nb04-·-json-chunking" aria-label="Permalink to &quot;nb04 · JSON chunking&quot;">​</a></h1><p><strong>Notebook:</strong> <code>notebooks/nb04_json_chunking.ipynb</code> · <strong>Status:</strong> done</p><h2 id="the-question" tabindex="-1">The question <a class="header-anchor" href="#the-question" aria-label="Permalink to &quot;The question&quot;">​</a></h2><p>nb02 covered Markdown, nb03 covered JS/Vue. This notebook covers the <code>.json</code> portion deferred by nb03. Unlike JS and Vue, which are each a single kind, JSON spans several different shapes — schemas, i18n dictionaries, package manifests, test fixtures — and each requires a different strategy.</p><h2 id="the-corpus" tabindex="-1">The corpus <a class="header-anchor" href="#the-corpus" aria-label="Permalink to &quot;The corpus&quot;">​</a></h2><p>After filtering (profile <code>js_vue_rag</code>, maximum file size 200 KB; <code>&gt;200</code> KB GeoJSON test dumps excluded by size), 60 JSON files are retained across 5 repos:</p><table><thead><tr><th>Category</th><th style="text-align:right;">Files</th><th style="text-align:right;">Size</th><th>Notes</th></tr></thead><tbody><tr><td>i18n_translations</td><td style="text-align:right;">16</td><td style="text-align:right;">~285 KB</td><td>translation dictionaries; 542 top-level keys, 4,464 leaves</td></tr><tr><td>schemas_validation</td><td style="text-align:right;">31</td><td style="text-align:right;">~68 KB</td><td>JSON Schema; 188 properties total (median 5/file, max 24)</td></tr><tr><td>test_fixtures</td><td style="text-align:right;">11</td><td style="text-align:right;">~39 KB</td><td>larger fixtures already removed by the size cap</td></tr><tr><td>package_tooling</td><td style="text-align:right;">14</td><td style="text-align:right;">—</td><td>project manifests</td></tr><tr><td>docs_meta / test_config / other</td><td style="text-align:right;">≤3 each</td><td style="text-align:right;">tiny</td><td></td></tr></tbody></table><p>The default indexed set is <code>schemas_validation</code>, <code>i18n_translations</code>, <code>docs_meta</code>, <code>test_config</code>. <code>package_tooling</code> and <code>test_fixtures</code> are excluded by default.</p><h2 id="why-one-strategy-is-not-sufficient" tabindex="-1">Why one strategy is not sufficient <a class="header-anchor" href="#why-one-strategy-is-not-sufficient" aria-label="Permalink to &quot;Why one strategy is not sufficient&quot;">​</a></h2><p>Each category has a different natural unit:</p><ul><li><strong>Schema</strong> — one property (field name → type + UI component + validation). The Kalisio extension nests <code>field: {component, label}</code>; the most common components are <code>KTextField</code> (54), <code>KSelectField</code> (35), <code>KTextareaField</code> (18). For form generation, one property is one retrieval unit.</li><li><strong>i18n</strong> — one top-level section (a component&#39;s or feature&#39;s strings). Files mix flat top-level labels with nested sections; maximum depth reaches 7. Splitting at every leaf would emit thousands of one-line chunks; splitting at the top-level key produces one chunk per section.</li><li><strong>package.json</strong> — little internal structure worth retaining; only <code>name</code> / <code>description</code> / <code>scripts</code> / dependency names are kept.</li><li><strong>Test fixtures and others</strong> — heterogeneous and low-signal; a generic JSON split is used as a fallback.</li></ul><p>For this reason strategy C is category-aware rather than a single rule.</p><h2 id="available-tooling" tabindex="-1">Available tooling <a class="header-anchor" href="#available-tooling" aria-label="Permalink to &quot;Available tooling&quot;">​</a></h2><table><thead><tr><th>Tool</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>RecursiveCharacterTextSplitter</code> (RCT)</td><td>Blind to JSON syntax; may split inside a string literal or between a key and its value.</td></tr><tr><td><code>RecursiveJsonSplitter</code></td><td>Parses the tree and descends until each sub-tree fits the size limit. Every chunk is a valid JSON sub-tree, but the name of the enclosing key is lost above the split point.</td></tr></tbody></table><h2 id="four-strategies" tabindex="-1">Four strategies <a class="header-anchor" href="#four-strategies" aria-label="Permalink to &quot;Four strategies&quot;">​</a></h2><p><strong>A</strong> RCT generic, <strong>B</strong> <code>RecursiveJsonSplitter</code>, <strong>C</strong> category-aware key split, <strong>D</strong> = C plus a <code>// &lt;rel_path&gt; :: &lt;unit&gt;</code> breadcrumb header.</p><h2 id="structural-experiment" tabindex="-1">Structural experiment <a class="header-anchor" href="#structural-experiment" aria-label="Permalink to &quot;Structural experiment&quot;">​</a></h2><p>60 files, <code>chunk_size = 500</code>. The metric <code>parse_integrity</code> is the fraction of chunks that parse as standalone JSON after stripping any <code>//</code> header line (analogous to nb02&#39;s <code>code_integrity</code>):</p><table><thead><tr><th>Strategy</th><th style="text-align:right;">Chunks</th><th style="text-align:right;">Mean</th><th style="text-align:right;">Max</th><th style="text-align:right;">Oversized</th><th style="text-align:right;">Parse integrity</th></tr></thead><tbody><tr><td>A — RCT</td><td style="text-align:right;">971</td><td style="text-align:right;">450</td><td style="text-align:right;">500</td><td style="text-align:right;">0.0%</td><td style="text-align:right;">0.7%</td></tr><tr><td>B — RecursiveJsonSplitter</td><td style="text-align:right;">946</td><td style="text-align:right;">380</td><td style="text-align:right;">499</td><td style="text-align:right;">0.0%</td><td style="text-align:right;">100%</td></tr><tr><td>C — category-aware</td><td style="text-align:right;">1,135</td><td style="text-align:right;">339</td><td style="text-align:right;">1,375</td><td style="text-align:right;">4.2%</td><td style="text-align:right;">100%</td></tr><tr><td>D — category + breadcrumb</td><td style="text-align:right;">1,135</td><td style="text-align:right;">388</td><td style="text-align:right;">1,432</td><td style="text-align:right;">4.6%</td><td style="text-align:right;">100%</td></tr></tbody></table><ul><li>A&#39;s parse integrity is ~0.7%: a random JSON-text slice is almost never a parseable document. For a code agent this is the same constraint as broken code fences in nb02.</li><li>C emits ~20% more chunks than B because each top-level property or section is its own unit, whereas B merges small sub-trees.</li><li>~4% of C/D chunks exceed <code>chunk_size × 1.5</code> (a single property holding a long <code>options</code> / <code>services</code> array). Splitting mid-property is treated as worse for retrieval than an oversized chunk.</li></ul><h2 id="retrieval-experiment" tabindex="-1">Retrieval experiment <a class="header-anchor" href="#retrieval-experiment" aria-label="Permalink to &quot;Retrieval experiment&quot;">​</a></h2><p>Gold set: 174 queries from two routes mined from the corpus — 104 i18n value-to-key (&quot;where is this string set in the app?&quot;) and 70 schema property-name (&quot;which schema defines field X with component Y?&quot;), across 48 files. Strategy A is excluded because §4 already showed its chunks are unparseable.</p><table><thead><tr><th>Strategy</th><th style="text-align:right;">hit@5</th><th style="text-align:right;">hit@10</th><th style="text-align:right;">MRR</th><th style="text-align:right;">i18n hit@5</th><th style="text-align:right;">schema hit@5</th></tr></thead><tbody><tr><td>B — RecursiveJsonSplitter</td><td style="text-align:right;">0.920</td><td style="text-align:right;">0.966</td><td style="text-align:right;">0.703</td><td style="text-align:right;">0.971</td><td style="text-align:right;">0.843</td></tr><tr><td>C — category-aware</td><td style="text-align:right;">0.948</td><td style="text-align:right;">0.989</td><td style="text-align:right;">0.752</td><td style="text-align:right;">0.990</td><td style="text-align:right;">0.886</td></tr><tr><td>D — category + breadcrumb</td><td style="text-align:right;">0.943</td><td style="text-align:right;">1.000</td><td style="text-align:right;">0.704</td><td style="text-align:right;">0.981</td><td style="text-align:right;">0.886</td></tr><tr><td><strong>F — D + BM25 (RRF)</strong></td><td style="text-align:right;"><strong>0.994</strong></td><td style="text-align:right;">0.994</td><td style="text-align:right;"><strong>0.846</strong></td><td style="text-align:right;"><strong>1.000</strong></td><td style="text-align:right;"><strong>0.986</strong></td></tr></tbody></table><ul><li>C scores higher than B (+2.8 pp hit@5, +4.3 pp schema hit@5). Category-aware splitting improves retrieval, not only chunk shape — a result the structural metrics alone could not establish.</li><li>D is approximately equal to C under dense-only retrieval (hit@5 0.943 vs 0.948; D&#39;s MRR is slightly lower, 0.704 vs 0.752). The ~50-token path header slightly reduces the dense embedding signal on short JSON chunks, so for dense-only retrieval the breadcrumb provides no benefit.</li><li>Hybrid (F) is the improvement: +5.1 pp hit@5 and +14 pp MRR over D. BM25 tokenizes the breadcrumb path (<code>crisis</code>, <code>schemas</code>, <code>events</code>, <code>create</code>) and produces a direct term match when a query names the component; this is the same result as nb03. Schema retrieval is harder than i18n under dense retrieval, because a <code>(property, component)</code> pair recurs across schemas; hybrid raises schema hit@5 from 0.886 to 0.986.</li></ul><h2 id="selected-strategy" tabindex="-1">Selected strategy <a class="header-anchor" href="#selected-strategy" aria-label="Permalink to &quot;Selected strategy&quot;">​</a></h2><p>Strategy <strong>D — category-aware key split + breadcrumb</strong>, retrieved with <strong>hybrid dense + BM25</strong> (matching the JS/Vue path). The breadcrumb&#39;s value here is lexical: it is realized by the BM25 component, not the dense embedding. For a dense-only deployment, C is the correct choice (marginally higher MRR, no header overhead).</p><p>Default index set: <code>schemas_validation</code>, <code>i18n_translations</code>, <code>docs_meta</code>, <code>test_config</code> (nb01&#39;s high and medium tiers plus the small <code>layers.json</code>). <code>package_tooling</code> remains excluded; the chunker provides a cleaned subset (<code>name</code> / <code>description</code> / <code>scripts</code> / dependency names) for callers that opt in. <code>test_fixtures</code> remain excluded, as their token mass is large payloads with no API-usage signal.</p><p>This is the JSON chunker in the <a href="/knowledge/architecture/ingestion-pipeline.html">ingestion pipeline</a>; the hybrid retrieval matches <a href="/knowledge/architecture/rag.html">RAG: indexing &amp; retrieval</a>.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>The gold queries are mined from the same corpus the chunker runs on, so hit@K measures within-corpus retrieval rather than generalization. The set is small (174 queries): differences below ~2 pp are within sampling noise.</li><li>Scoring used MiniLM-L6-v2 for notebook runtime. The relative ordering of strategies is robust across embedding models, but absolute values differ under the production model.</li><li>i18n files are indexed per language (<code>core_en.json</code> and <code>core_fr.json</code> separately); the chunker does not merge translations across languages.</li><li>A schema property is the smallest unit and is never split, so ~12% of schema chunks exceed <code>chunk_size × 1.5</code> when a single property holds a long array.</li></ul>',30),n=[s];function o(d,l,h,c,g,u){return i(),e("div",null,n)}const m=t(r,[["render",o]]);export{y as __pageData,m as default};
